// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.prank(actor);
        SimpleSuicide c2 = new SimpleSuicide();
        address originalOwner = c2.smartfix_owner();
        vm.prank(actor);
        bool ok = true;
        try c2.sudicideAnyone() { ok = true; } catch { ok = false; }
        assertTrue(actor != originalOwner || ok);
    }
}
